const items = $input.first().json;
const ytIds = (Array.isArray(items) ? items : []).filter(i=>i.yt_id).map(i=>i.yt_id);
const batchSize = 50;
const batches = [];
for (let i=0;i<ytIds.length;i+=batchSize) {
  batches.push({ json: { ytIds: ytIds.slice(i,i+batchSize), batch: Math.floor(i/batchSize)+1 } });
}
console.log(`Checking ${ytIds.length} YouTube IDs in ${batches.length} batches`);
return batches;

const items = $input.all();
const dead = [], alive_count = [];
let checked = 0;
for (const item of items) {
  const d = item.json;
  checked += d.checked || 0;
  if (d.dead?.length) dead.push(...d.dead);
  alive_count.push(d.alive || 0);
}
const alive = alive_count.reduce((a,b)=>a+b,0);
console.log(`✅ Verification: ${alive} alive, ${dead.length} dead`);
return [{ json: { checked, alive, dead, dead_count: dead.length, checked_at: new Date().toISOString() } }];

// Mark dead content as hidden in Supabase
const { dead } = $input.first().json;
const SB_URL  = 'https://wadazxpofizrfoczhmkn.supabase.co/rest/v1';
const SERVICE = process.env.SUPABASE_SERVICE || 'FILL_SERVICE_KEY';

let hidden = 0;
for (const ytId of dead) {
  await fetch(`${SB_URL}/content?yt_id=eq.${ytId}`, {
    method: 'PATCH',
    headers: {
      'apikey': SERVICE, 'Authorization': `Bearer ${SERVICE}`,
      'Content-Type': 'application/json', 'Prefer': 'return=minimal'
    },
    body: JSON.stringify({ status: 'hidden' })
  }).catch(()=>{});
  await fetch(`${SB_URL}/episodes?yt_id=eq.${ytId}`, {
    method: 'DELETE',
    headers: { 'apikey': SERVICE, 'Authorization': `Bearer ${SERVICE}` }
  }).catch(()=>{});
  hidden++;
}
console.log(`Hidden ${hidden} dead items`);
return [{ json: { hidden, dead, report: `${hidden} liens morts masqués automatiquement` } }];
